lint-sweep.script:
export const meta = {
  name: 'lint-sweep',
  description: 'Lint every package in sequence, then summarize the findings',
  phases: [{ title: 'Lint', detail: 'one package at a time' }, { title: 'Report' }],
}
const PKGS = ['api', 'auth', 'billing', 'cache', 'db', 'events', 'jobs', 'web']
phase('Lint')
const found = []
for (const p of PKGS) {
  found.push(await agent(`Run golangci-lint on ./pkg/${p}/... and return every finding as file:line: message.`, { label: `lint pkg/${p}`, phase: 'Lint', model: 'haiku' }))
}
phase('Report')
return await agent(`Summarize these lint findings by severity: ${found.join('\n')}`, { label: 'report', phase: 'Report', model: 'haiku' })
